import{_ as t,o,c as r,a2 as n}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Changelog","description":"Release history and version changelog for AzureScout.","frontmatter":{"description":"Release history and version changelog for AzureScout."},"headers":[],"relativePath":"project/changelog.md","filePath":"project/changelog.md"}'),a={name:"project/changelog.md"};function s(d,e,i,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>The full changelog is maintained in the repository root and rendered on GitHub.</p><p><a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">View CHANGELOG.md on GitHub</a></p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>AzureScout follows <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> format and <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><table tabindex="0"><thead><tr><th>Version</th><th>Highlights</th></tr></thead><tbody><tr><td><strong>v3.5.0</strong> (2026-08-04)</td><td><strong>The report is a product, not a page.</strong> The owner-approved v6 design ships: the React report becomes a <strong>multi-page application</strong> — Overview, Inventory &amp; audit, Assessments, Diagrams, Data &amp; drift, Remediation plan — rendered from the run&#39;s own data. Inventory becomes a blade view on the documented <strong>18-category taxonomy</strong> with every collector listed including zeros, filterable/sortable item tables, tenant structure, audit callouts and a full cost-optimization blade. Each assessment carries the <strong>complete conformance register</strong>: every check, a gap block for every fail (resource-grain evidence, why it matters, numbered fix, per-check Learn link), the manual review agenda, and a What&#39;s-next section. A Diagrams page adds MG hierarchy, VNet/subnet IP utilization, estate and gaps figures with full-screen zoom. Executive/Consultant/Data become a depth toggle; exports add <strong>Markdown and JSON</strong>. Conformance clause R-04 is enforced for real — the renderer no longer re-invokes the scoring engine. All other assessment formats remain <strong>on hold</strong>. See AB#6928, AB#6936, AB#6937, AB#6938, AB#7035.</td></tr><tr><td><strong>v3.3.4</strong> (2026-08-04)</td><td><strong>One report, and it is the deliverable.</strong> Reading a full multi-tenant render end to end found all six rendered formats weak in a different way — a blank dashboard, a 10/10 maturity score with no explanation, documents that never named their assessment, text over text in the PDF, figures off the slide, a Word file that opened with a repair prompt. The <strong>React single-page report</strong> is now the deliverable: one adaptive page hosting inventory and every assessment, navigation built from what actually ran, each assessment answering what was run / what was found / what to fix per CAF/WAF, and every score shown with its numerator, denominator and exclusions. Every other rendered format is <strong>on hold</strong> and will be regenerated from that report; <code>Json</code>/<code>JsonEvidence</code> are data and are never held; a held format asked for by name warns and still renders React, so a run never returns an empty folder. Also fixes a cited Learn guidance URL that 404&#39;d while stamped &quot;verified&quot;, plus a link-rot audit over all 26 citations. See AB#6922, AB#6913.</td></tr><tr><td><strong>v3.3.3</strong> (2026-08-03)</td><td><strong>The corpus told the truth — five collection defects, none visible from a green suite.</strong> The v3.3.2 vault fix never reached the collect result (dead hashtable-PSObject guard + a copy loop that never visited the key); Export-Pptx&#39;s module-scope <code>Get-ScoutProp</code> shadowed the collect walker and nulled every nested <code>properties.*</code> read on product runs — the defect that corrupted the banked corpus; management groups collected for the first time in the product&#39;s history (<code>-UseTenantScope</code>, 92 MGs across 8 reference tenants); <code>security.defenderPlans</code> collected per subscription instead of hardcoded <code>@()</code> while CAF/WAF rules queried it; same-second runs no longer overwrite each other&#39;s run folder. Adds the committed corpus harness with integrity checks and per-collector coverage verdicts (36 working, 0 unexplained empties). See AB#6896–AB#6903.</td></tr><tr><td><strong>v3.3.2</strong> (2026-08-03)</td><td><strong>Field fixes from real tenant runs.</strong> Advisor ingestion contained per subscription (one unregistered <code>Microsoft.Advisor</code> provider no longer costs the tenant every recommendation); Entra ID P2-gated Graph features report <code>NOT LICENSED — requires Microsoft Entra ID P2</code> instead of <code>DENIED</code>; Recovery Services vaults collected from rows the raw pass already holds instead of a hardcoded empty array; the LandingZone rule glob scoped to its own 13 areas (was sweeping in 34); <code>GovernanceReport</code> reachable from <code>-OutputFormat All</code>; evidence truncation made visible (&quot;25 of 198 matched&quot;). Adds the customer-facing overview and least-privilege access guide plus licence-tier documentation. See AB#6893–AB#6895, AB#6890, AB#6863, AB#6864.</td></tr><tr><td><strong>v3.3.1</strong> (2026-08-03)</td><td><strong>Figures reach every format, and the Power BI pages actually bind.</strong> Figures embed in PowerPoint and PDF, not only Word (the PDF route needed no JPEG — <code>/FlateDecode</code> is zlib, which the rasteriser already emits). Power BI visual containers get all three required blobs (<code>config</code>, <code>query</code>, <code>dataTransforms</code>) instead of only <code>config</code>, so pages bind data instead of drawing empty frames. Verified by re-rendering all eight reference tenants offline: 29 artefacts each, 0 empty. See AB#6883, AB#6886.</td></tr><tr><td><strong>v3.3.0</strong> (2026-08-03)</td><td><strong>The reports become deliverables (Epic AB#6450).</strong> <code>docs/design/report-conformance.md</code> is normative (40 clauses) and the conformance suite asserts every automatic clause against an emitted package read back off disk. Word gains real styles, chapter numbering, a theme, header/footer with live PAGE fields, a TOC, a cover and appendices. Figures rasterise to PNG in managed code — no Graphviz, headless browser or System.Drawing. Power BI becomes a PBIP project (TMDL semantic model, relationships, measures, authored pages) instead of four CSVs. The deck states what was not assessed; the workbook gains a cover, full ARM ids and triage verdicts.</td></tr><tr><td><strong>Unreleased</strong></td><td><strong>Hardening pass over real-world collection and reporting failures.</strong> <code>-InventoryAndAssessment</code>/<code>-Both</code> makes the collect-once inventory+assessment path reachable from a script, not just the wizard. Tenant-wide collection (management groups, custom role/policy definitions) is unconditional instead of gated behind a dead switch. Two new evidence artifacts (<code>raw-inventory.json</code>, <code>collector-rowcounts.json</code>) and a per-collector permission-impact table replace a bare pre-flight verdict. Fifteen per-category assessment names are prefixed <code>Assess: </code> to stop colliding with inventory category names. A resource-type existence gate found eight real defects; six collectors retired, three corrected, 242 → 236. See <strong>Epic AB#6731</strong> and <a href="https://github.com/thisismydemo/azure-scout/blob/main/CHANGELOG.md#unreleased" target="_blank" rel="noreferrer">CHANGELOG.md <code>[Unreleased]</code></a>.</td></tr><tr><td><strong>v3.2.0</strong> (2026-08-01)</td><td><strong>Deep governance and compliance analytics.</strong> Scout goes from one real assessment to roughly twenty-eight, and from one enumerated source framework to all fourteen. Five WAF pillars, eight CAF landing-zone design areas, the WAF Maturity Model, MCSB plus one assessment per assigned regulatory initiative, Cloud Governance across seven risk categories with a 1-10 maturity report, and the AI, AVD, AVS, AVS Landing Zone, CASA, Azure Local, FinOps and DevOps reviews. <code>NotAssessed</code> is now a first-class status excluded from every denominator, so a control nobody chose to evaluate no longer reads as a pass. Two false-pass rules removed and <code>waf.storage.yaml</code> retired — it scored a WAF pillar WAF does not define. <code>Hybrid/ArcSites</code> and <code>Hybrid/VirtualMachines</code> re-sourced off Resource Graph, which indexes neither; verified live against real estates. See Epic AB#6454.</td></tr><tr><td><strong>v3.1.0</strong> (2026-07-31)</td><td><strong>Eighteen-category service coverage.</strong> Added the missing <code>Migration</code>, <code>General</code> and <code>DevOps</code> categories plus 62 collectors — measured service coverage rises from 41% to 66%. Removed the Resource Graph exclusion that hid Logic Apps in every prior release. Added child-resource collection (Key Vault secret/key expiry, blob containers with public-access level, file shares, lifecycle policies, Backup vault instances) — control plane only, Reader-only. Added a declarative cross-resource join to the rule engine with six rules, including &quot;which VMs have no backup&quot;. Added the SMART migration-readiness assessment on a date-stamped published-source enumeration. Fixed a golden suite that failed on any day but its recording date, and a wizard that never listed the real assessments. See Epic AB#6741.</td></tr><tr><td><strong>v3.0.9</strong> (2026-07-30)</td><td><strong>Live-run hardening.</strong> Fixed two fatal crashes found live against a real 8-subscription tenant (JSON report export <code>.Count</code>-on-null under StrictMode; SupportTickets null-date collector), isolated each report format behind its own try/catch, removed a permanently-broken Arc CPU metrics call, added retry/backoff to the operational-enrichment ARM helper, quieted an expected ReplicationEligibility 404, closed the wizard&#39;s Scope/Entra silent-default gap, added a Cost Data module pre-flight check, and clarified a DefenderAlerts null-reference message. See Epic AB#6731.</td></tr><tr><td><strong>v3.0.8</strong> (2026-07-29)</td><td>Suppress Az module breaking-change warnings in non-debug output.</td></tr><tr><td><strong>v3.0.7</strong> (2026-07-29)</td><td>Avoid a StrictMode <code>VariableIsUndefined</code> error on common parameters (e.g. <code>-Debug</code>).</td></tr><tr><td><strong>v3.0.6</strong> (2026-07-28)</td><td>Resilience and logging improvements for the Excel report build and ARC-enabled server collection.</td></tr><tr><td><strong>v3.0.5</strong> (2026-07-28)</td><td><strong>VM cost-row regression correction.</strong> Cost Management nested result rows no longer skip the production VM collector. See <a href="./releases/v3.0.5.html">v3.0.5</a>.</td></tr><tr><td><strong>v3.0.4</strong> (2026-07-28)</td><td><strong>VM runtime regression correction.</strong> Repeated Compute SKU <code>MemoryGB</code> values no longer skip the production VM collector. See <a href="./releases/v3.0.4.html">v3.0.4</a>.</td></tr><tr><td><strong>v3.0.3</strong> (2026-07-28)</td><td><strong>Production runtime collection.</strong> Hardened ARM-child, storage, and security/policy collectors now run in the standard extraction path. See <a href="./releases/v3.0.3.html">v3.0.3</a>.</td></tr><tr><td><strong>v3.0.2</strong> (2026-07-28)</td><td><strong>Runtime collector hardening.</strong> Retired App Insights endpoints are not queried, and storage service-property lookups run in the owning subscription. See <a href="./releases/v3.0.2.html">v3.0.2</a>.</td></tr><tr><td><strong>v3.0.1</strong> (2026-07-28)</td><td><strong>Tenant-scoped authentication and wizard correction.</strong> Every Azure context switch binds the requested tenant; a verified live run makes no unrelated-tenant authentication attempts. Interactive common parameters no longer suppress the wizard. See <a href="./releases/v3.0.1.html">v3.0.1</a>.</td></tr><tr><td><strong>v3.0.0</strong> (2026-07-28)</td><td><strong>Epic AB#5638 engine rebuild.</strong> The 174-definition declarative collector catalog now powers collection and reporting under StrictMode; the retired collector-script tree and imperative fallback are gone. Canonical contracts cover 174 ordered row sets and 348 worksheet cases. See <a href="./releases/v3.0.0.html">v3.0.0</a>.</td></tr><tr><td><strong>v2.11.0</strong> (2026-07-26)</td><td><strong>138 of 176 collectors declarative, and the definitions gated in CI.</strong> <s>Epic AB#5638 completes.</s> <strong>Correction: it does not</strong> -- the epic was closed prematurely and has been <strong>reopened</strong>; everything below shipped, but <code>Modules/</code> still holds 221 <code>.ps1</code>, the collector folder still holds 176, 138 of 176 are declarative, 20 StrictMode weakening sites remain (4 live), and reporting is not cut over. See the <a href="./roadmap.html#the-engine-rebuild-is-in-progress-not-complete">roadmap</a>. The audit had classified 20 cross-resource-join collectors as escape-hatch alongside those making live cmdlet calls; re-examining all 48 showed its reasons were right but its inference was not -- <strong>a cross-resource join is not the same thing as a live cmdlet call</strong>, since each filters the already-collected set a second time and correlates over data the pipeline already holds. Two schema keys (<code>SetupPreamble</code> / <code>SetupVariables</code>, declared rather than harvested) unlocked 14 conversions. Verified live: <strong>138 declarative, 36 imperative</strong>. <strong>Definitions are now gated in CI</strong> before the test suite, including a <strong>drift check</strong> that regenerates each definition from its source collector and requires a byte-for-byte match -- added because a definition <strong>had already drifted for a release while its equivalence test stayed green</strong>, since with StrictMode off the stale and current accessors agreed on the fixture. The gate is proven to fail, not assumed to: 13 tests each write a deliberately broken definition and assert the message names the fault. <strong>Fixed:</strong> the conversion tool could never have handled <code>Web/APPServicePlan</code> correctly -- it treated every filtered assignment as a row source, so that collector&#39;s secondary filter would have been lifted onto the row set and <strong>silently dropped every app service plan</strong>; plus a non-reproducible fixture generator, case-variant duplicate JSON keys, and a missing pipeline pass-through that left joined columns null on <strong>both</strong> paths and therefore passed equivalence. <strong>Honest limit:</strong> of the 14 conversions, only 5 have the join itself exercised by the fixture; the other 9 agree while both paths take the not-found branch, and each is pinned by name so the list can only shorten. <strong>Not done:</strong> reporting is still not cut over</td></tr><tr><td><strong>v2.10.0</strong> (2026-07-26)</td><td><strong>The declarative collectors actually run</strong> — v2.9.0 converted 124 of 176 collectors to <code>.psd1</code> definitions but <strong>nothing called the interpreter</strong>, so the live pipeline still executed the imperative <code>.ps1</code> for every collector and the conversion delivered nothing to a user. Routing now uses the <code>HasDeclarativeDefinition</code> / <code>DefinitionPath</code> that <code>Get-ScoutCollector</code> already reported; verified live, the run log shows <strong>124 declarative / 50 imperative</strong>. Proving it needed a different technique than the conversion did — a row comparison can never detect a routing regression, since both paths agree by construction — so the proof is by impossibility: a fixture collector whose entire imperative branch is a <code>throw</code> completes successfully, and fails with that exact message when the kill switch is on. A full pass over an 845-resource estate gave <strong>1654 rows either way, zero deltas, byte-identical ReportCache JSON</strong>. <strong>Kill switch:</strong> <code>AZURESCOUT_FORCE_IMPERATIVE_COLLECTORS=1</code>, an env var so it works on an installed build. <strong>The non-ARG collection half is inverted</strong> — <code>Get-ScoutApiResources</code>, <code>Get-ScoutVmQuotas</code>, <code>Get-ScoutVmSkuDetails</code> and <code>Get-ScoutCostInventory</code>, dead since v2.7.0, are now the real path with the v1 implementations retired to shims and pinned by AST tests. <strong>Fixed:</strong> two shape regressions from <code>@()</code> wrapping — <code>CostData</code> in an array made the anomaly detector return <strong>zero records with no error</strong>, and unrolling changed the shape of every single-row endpoint response; and <code>Management/ManagementGroups</code>, whose fallback had been returning nothing on every run, making this <strong>the first release with zero collector failures</strong> (that sheet still needs Management Group Reader at the root to carry rows). <strong>Not done:</strong> reporting is not cut over — <code>Start-AZSCExcelJob</code> still runs each collector&#39;s <code>.ps1</code> reporting branch through its own duplicate discovery</td></tr><tr><td><strong>v2.9.0</strong> (2026-07-26)</td><td><strong>The collectors become data and the module runs strict</strong> — <strong>124 of 176</strong> collectors are now <code>.psd1</code> definitions rather than PowerShell (up from 13), each pinned by an equivalence test comparing the imperative and declarative paths key-by-key on rows <em>and</em> cell-by-cell on the written <code>.xlsx</code>, under both tag modes. That gate caught <strong>six interpreter defects</strong>, including a field whose source is an <code>if</code>/<code>else</code> <em>statement</em> being silently unreachable, dropped per-loop preambles that emptied <code>Security/Vault</code>&#39;s permission columns, and a dropped filter preamble that made <code>AI/AppliedAIServices</code> produce a silently empty sheet. <strong>All 174 collectors now pass under <code>Set-StrictMode -Version Latest</code></strong>, proved real by diffing emitted rows before and after with StrictMode off (20 of 23 byte-identical), with an AST-parsed CI guard against weakening it. <strong>Fixed:</strong> AB#402 error detection had gone blind — it compared <code>$Error.Count</code> across a phase, but <code>$Error</code> is a fixed-size ring buffer, so once saturated the delta is permanently zero and non-terminating errors stopped being reported entirely; <code>ChartP6</code>, where a worksheet that exists but holds no cells has a <code>$null</code> dimension so the pivot range lookup threw and took the chart with it; and an out-of-scope subscription name that had changed from <code>$null</code> to <code>&#39;&#39;</code>, making one estate render two different blanks. <strong><code>Management/ManagementGroups</code> was never a StrictMode fault</strong> — it fails parameter binding on <code>Get-AzManagementGroup -Expand -Recurse</code> with no <code>-GroupId</code>, explaining the long-standing live-run failure. <strong>Limits:</strong> the equivalence fixtures are generated from each definition&#39;s AST, not recorded from a tenant, and the live pipeline still executes the imperative <code>.ps1</code> for every collector</td></tr><tr><td><strong>v2.8.0</strong> (2026-07-26)</td><td><strong>Collection actually happens once</strong> — a default assessment collect now issues <strong>4</strong> Resource Graph queries instead of <strong>35</strong> (AB#5648). v2.7.0 shipped the single-pass collection functions but nothing called them, so the round-trip count was unchanged; they are now the real path. Both numbers were re-derived by counting invocations against a stub in place of <code>Search-AzGraph</code> and are pinned by hard count assertions, because a query count with no test regresses silently. It is 4 rather than 1 for stated reasons: three raw tables plus <code>sqlDefenderPricing</code>, which reads <code>SecurityResources</code> and cannot be served from inventory. Inventory extraction stays at 8 because those are eight <em>distinct</em> ARG tables, not filters over one — what changed there is ownership, not count: one paging implementation instead of two. The legacy paging/batching/retry engine <code>Invoke-AZTIInventoryLoop.ps1</code> is <strong>deleted</strong> and <code>Start-AZTIGraphExtraction</code> is now a shim that issues no ARG call, both enforced by AST-based tests. <strong>Fixed:</strong> the inverted path returned an empty <code>tags</code> array for every estate — a blank report section, no error, invisible to all 2144 passing tests — because the raw pass omits the <code>tags</code> column unless asked while the contract aggregates its top-level <code>tags</code> key from <code>subscriptions[*].tags</code>. <strong>Trade-offs, unmeasured:</strong> the raw pass carries the full <code>properties</code> bag, so 1000-row page counts can rise even as query counts fall, and <code>-Categories</code> no longer reduces what is fetched, only what is shaped; <code>-Source TypedQueries</code> remains supported at 35 queries. <strong>Not done:</strong> the non-ARG half — <code>Get-ScoutApiResources</code>, <code>Get-ScoutVmQuotas</code>, <code>Get-ScoutVmSkuDetails</code> and <code>Get-ScoutCostInventory</code> are still dead code and a live run uses the v1 ARM REST, quota/SKU and Cost Management paths</td></tr><tr><td><strong>v2.7.0</strong> (2026-07-26)</td><td><strong>Reporting leaves <code>Modules/</code> and Excel COM is deleted</strong> — second phase of the engine rebuild. All 26 inventory renderers moved to <code>src/report/renderers/</code>, each file renamed to match the function it defines, and <code>Build-AZTIExcelComObject.ps1</code> removed outright; chart styling runs on EPPlus/ImportExcel only. COM is why <code>-Lite</code> defaulted to true and why the module surfaced a raw <code>0x80040154</code> on every machine and CI runner without Excel. Verified live on a machine with no Excel: a 42-worksheet workbook with <code>SecurityCenter</code> at 489 rows. <strong>The 13 Databases collectors became <code>.psd1</code> data</strong> interpreted at runtime, each pinned by an equivalence test comparing the imperative and declarative paths row-by-row and cell-by-cell under both tag modes — which caught two interpreter defects that would have silently changed shipped reports (tag columns appended rather than inserted; <code>ResourceTypes</code> treated as a membership test rather than a grouping). An AST audit of all 176 collectors ships alongside: 115 of the remaining 163 are mechanically convertible, 48 must stay hand-written. <strong>A single-pass collection layer landed as capability only</strong> — five new <code>src/collect/</code> functions and a 128-type map, one raw pass satisfying 34 of 35 collect queries, but no production caller yet, so ARG round-trips are unchanged from v2.6.0 (inversion is AB#5648). <strong>Fixed:</strong> an unbound <code>[string[]]</code> is <code>$null</code> and <code>@($null).Count</code> is 1, so <code>Invoke-Collect</code>&#39;s subscription-resolution branch never fired on the default path — the subscription list was never derived from <code>resourcecontainers</code> and every later table degraded to one un-batched tenant-wide call with no per-batch isolation</td></tr><tr><td><strong>v2.6.0</strong> (2026-07-25)</td><td><strong>The engine no longer uses background jobs</strong> — first phase of the engine rebuild. Processing created one <code>Start-Job</code> per category, each creating one <code>[PowerShell]::Create()</code> runspace per collector; every defect of the v2.5.x wave lived in that coordination rather than in the collectors. All 176 collectors now run <strong>in-process in a fixed order</strong>, so identical input yields an identical report cache — proven against a live tenant across two consecutive runs. One collector&#39;s failure no longer empties its category or aborts the batch, and <code>Wait-AZSCJob</code> and the job machinery are deleted. <strong>Fixed, all pre-existing and all invisible behind the job boundary:</strong> the <strong>Security Center worksheet had been empty in every release that had one</strong>; five collectors threw on their first log call; per-file <code>.CATEGORY</code> filtering had never matched a file; the Excel loop ran every collector regardless of data because <code>@($null).Count</code> is 1, not 0; and all four exporters read the cache unguarded</td></tr><tr><td><strong>v2.5.3</strong> (2026-07-25)</td><td><strong>A normal Azure response aborted the run</strong> — <code>The property &#39;ReservationRecomen&#39; cannot be found on this object</code> killed a full inventory against a real tenant. Not a null-reference fault: the module runs under StrictMode, where member enumeration over a collection reports the property missing when the enumeration yields <em>nothing at all</em> — which is what an <strong>empty</strong> collection on every element produces. Azure returns <code>{ &quot;value&quot;: [] }</code> for a subscription with no reservation recommendations, so a healthy tenant crashed. Swept the same class out of the VM quota and SKU collectors (a bare <code>$_.subscriptionId</code> over a mixed array meant <strong>no</strong> subscription got quotas), fixed a diagram job wait that never waited, and stopped an unavailable Cost Management API destroying the whole report. <strong>New:</strong> every run now writes <code>scout-run.log</code> and <code>scout-console.log</code> into its run folder — phases, counts, warnings, and the full error record with script, line and stack trace on failure</td></tr><tr><td><strong>v2.5.2</strong> (2026-07-25)</td><td><strong>Determinism</strong> — a whole report category could silently vanish from a run. A job-wait race meant a still-<code>NotStarted</code> job was never waited on, then harvested and destroyed empty, so <code>Compute.json</code> came back 5,158 bytes on one run and 470 on the next. Both the wait loop and the batch filter now treat every non-terminal state as pending, a dropped category now warns instead of failing silently, and a machine without Excel gets a plain explanation rather than a raw COM <code>0x80040154</code> error</td></tr><tr><td><strong>v2.5.1</strong> (2026-07-25)</td><td><strong>Seven live-run fixes</strong> — a full inventory run could not complete against a real tenant; extraction and processing succeeded, then the reporting layer threw after every worksheet had been built. Fixes an uninitialised extraction variable, 41 <code>.IsPresent</code> reads on untyped parameters, Excel styling/tables on empty worksheets, VM property names the collector never emitted, 29 unguarded worksheet dereferences, 10 pivot titles read before assignment, and a Markdown string-interpolation bug. All seven were found by running against live Azure, not by the test suite</td></tr><tr><td><strong>v2.5.0</strong> (2026-07-25)</td><td><strong>One collection pass</strong> — a combined inventory + assessment run now queries Azure once instead of twice. The assessment shapes its scalars from the rows the inventory pass already fetched (<code>ConvertFrom-ScoutInventory</code>, <code>-FromInventory</code>); only the Defender for SQL pricing lookup still reaches Resource Graph, because it reads a table inventory does not collect. Assessment-only runs are unchanged</td></tr><tr><td><strong>v2.4.0</strong> (2026-07-25)</td><td><strong>One command</strong> — inventory and assessment became modes of <code>Invoke-AzureScout</code> rather than two cmdlets (<code>-Assessment</code>, <code>-CollectOnly</code>, <code>-FromCollect</code>); assessment mode now honours the inventory sign-in parameters; <code>-OutputFormat</code> widened to accept several renderers in one run. A <strong>guided setup wizard</strong> opens when <code>Invoke-AzureScout</code> is run with no parameters at a terminal, and never fires in CI. <code>Invoke-ScoutAssessment</code> is deprecated for removal in v3.0.0</td></tr><tr><td><strong>v2.3.0</strong> (2026-07-25)</td><td>Run isolation (each invocation gets its own run folder, <code>-RunName</code>, <code>-Force</code>, <code>Clear-AZSCCacheFolder -OlderThan</code>), the caller&#39;s subscription context restored after multi-subscription runs, a post-login management-group probe, <strong>Azure DevOps inventory</strong> via <code>-IncludeDevOps</code> (five worksheets plus service-connection-to-subscription cross-reference), a composite <code>action.yml</code> for GitHub Actions, and new automation, category-reference, and validation-matrix documentation</td></tr><tr><td><strong>v2.2.0</strong> (2026-07-24)</td><td>Four new report tiers (<code>Word</code>, <code>EChartsDashboard</code>, <code>Pdf</code>, <code>JsonEvidence</code>), Excel visual dashboard tabs, a much richer interactive React report (topology, MG hierarchy, KPI cards, Governance section, drill-downs) + <code>report.pbit</code> generation, new offline analysis (<code>Get-ScoutInventoryDrift</code>, <code>Get-ScoutCostAnomaly</code>, <code>Get-ScoutIacGap</code>), IoT deep coverage (DPS + Digital Twins), tag aggregation, deeper Database/Analytics/IoT rule automation, collector/pipeline resilience, assessment config load/save (<code>Import-ScoutConfig</code>/<code>Export-ScoutConfig</code>), a CI pipeline, a real <code>azure-inventory</code> workflow, and five v1 inventory bug fixes</td></tr><tr><td><strong>v2.1.0</strong> (2026-07-23)</td><td>Native governance collector (<code>Import-Governance</code>, no more AzGovViz dependency by default), unattended one-command pipeline (<code>Invoke-ScoutPipeline</code>), and a React report + cross-run drift tracking (<code>-OutputFormat React</code>, <code>Get-ScoutDrift</code>)</td></tr><tr><td><strong>v2.0.0</strong></td><td><strong>CAF/WAF Assessment Platform</strong> — read-only assessment engine (139 rules across 8 CAF design areas + 5 WAF pillars), ARG collect layer, AzGovViz/Advisor/ARG ingest, ALZ benchmark, tiered reporting (Power BI / HTML / OpenXML PowerPoint / Excel / JSON), per-domain analytics via <code>Invoke-ScoutAssessment</code>. Runtime-verified offline + live tenant. Breaking: <code>findings.json</code> contract; assessment requires PowerShell 7</td></tr><tr><td><strong>v1.0.0</strong></td><td>Full rename to AzureScout (AZSC prefix), 154 ARM modules, 17 Entra ID modules, Excel + JSON + Markdown + AsciiDoc output, draw.io diagrams, permission pre-flight, category filtering</td></tr></tbody></table>',6)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
